364	  $('facts').innerHTML = `<span><b>${esc(name)}</b></span><span>${X} × ${Y} px × ${Z} slices` +
365	    `${meta.bin > 1 ? ` (shown binned ${meta.bin}×)` : ''}</span>` +
366	    `<span>${um ? um.toFixed(2) + ' µm/px (from the file)' : 'pixel size unknown'}</span>` +
367	    `<span class="${meta.z_step_um ? '' : 'guess'}">${meta.z_step_um ? 'slice spacing ' + meta.z_step_um + ' µm' : 'slice spacing unknown'}</span>` +
368	    (meta.frames > 1 ? `<span class="guess">time point 1 of ${meta.frames}</span>` : '');
369	  uploadChannels();
370	  if (!bound) { bind(); bound = true; }
371	  sync(); flat();
372	}
373	// Loading: a stack from this computer (the Load button or a drop anywhere on the page) or from Google
374	// Drive, read in the browser, turned into volumes and handed to the viewer.
375	import { openTiff, TiffError } from './tiff.js';
376	import { buildVolumes, binFor } from './stack.js';
377	import * as drive from './drive.js';
378	import { show, maxTextureSide } from './viewer.js';
379	
380	const $ = (id) => document.getElementById(id);
381	const SOURCE = 'mv-load-source', DRIVE_LINK = 'mv-drive-link';
382	const store = {
383	  get(k, d) { try { return localStorage.getItem(k) ?? d; } catch { return d; } },
384	  set(k, v) { try { localStorage.setItem(k, v); } catch { /* no storage: remembered for this visit only */ } },
385	};
386	const esc = (s) => String(s).replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
387	const mb = (n) => (n / 1048576).toFixed(1);
388	
389	let busy = false;
390	function progress(text, frac) {
391	  $('viewer').hidden = true; $('empty').hidden = false; $('empty-msg').textContent = '';
392	  $('progress').hidden = false; $('progress-text').textContent = text;
393	  $('progress-bar').firstElementChild.style.width = frac == null ? '0' : `${Math.round(frac * 100)}%`;
394	}
395	function failed(err) {
396	  busy = false;
397	  $('progress').hidden = true; $('viewer').hidden = true; $('empty').hidden = false;
398	  $('empty-msg').textContent = err instanceof TiffError ? `Could not read this file: ${err.message}.` : `Could not open the stack: ${err.message || err}`;
399	  if (!(err instanceof TiffError)) console.error(err);
400	}
401	
402	async function openBytes(name, bytes) {
403	  busy = true;
404	  try {
405	    const side = maxTextureSide();
406	    progress(`Reading ${name}…`, 0);
407	    const stack = openTiff(bytes);
408	    if (stack.slices < 2) throw new TiffError('it holds a single plane, not a stack of slices');
409	    if (stack.slices > side) throw new TiffError(`it has ${stack.slices} slices; this browser draws at most ${side}`);
410	    const bin = binFor(stack.width, stack.height, Math.min(640, side));
411	    const { meta, vols } = await buildVolumes(stack, { bin, onProgress: (done, total) =>
412	      progress(`Reading ${name}: ${done} of ${total} planes`, done / total) });
413	    $('progress').hidden = true; $('empty').hidden = true; $('viewer').hidden = false;
414	    document.title = `${name} · 3D MicroViewer`;
415	    show(name, meta, vols);
416	    busy = false;
417	  } catch (err) { failed(err); }
418	}
419	
420	async function openFile(f) {
421	  if (busy || !f) return;
422	  progress(`Reading ${f.name} (${mb(f.size)} MB)…`, 0);
423	  try { await openBytes(f.name, await f.arrayBuffer()); } catch (err) { failed(err); }
424	}
425	
426	$('file').onchange = (e) => { openFile(e.target.files[0]); e.target.value = ''; };
427	for (const ev of ['dragenter', 'dragover']) document.addEventListener(ev, (e) => { e.preventDefault(); document.body.classList.add('over'); });
428	document.addEventListener('dragleave', (e) => { if (!e.relatedTarget) document.body.classList.remove('over'); });
429	document.addEventListener('drop', (e) => {
430	  e.preventDefault(); document.body.classList.remove('over');
431	  openFile(e.dataTransfer.files[0]);
432	});
433	
434	function load(src) {
435	  store.set(SOURCE, src); $('load-menu').open = false;
436	  if (src === 'local' || !drive.ready) return $('file').click();
437	  $('drive-link').value = store.get(DRIVE_LINK, '') || drive.defaultLink;
438	  $('drive-dlg').showModal(); $('drive-link').select();
439	  if (drive.parse($('drive-link').value)?.kind === 'folder') $('drive-go').click();
440	}
441	$('load-main').onclick = () => load(store.get(SOURCE, 'local'));
442	document.querySelectorAll('#load-menu .item').forEach((b) => (b.onclick = () => load(b.dataset.src)));
443	document.addEventListener('click', (e) => { if (!$('load-menu').contains(e.target)) $('load-menu').open = false; });
444	
445	// the Drive dialog: a pasted file link loads at once; a folder link lists its stacks and subfolders
446	{
447	  const msg = (t, err) => { const m = $('drive-msg'); m.textContent = m.title = t; m.classList.toggle('err', !!err); };
448	  const sizeText = (n) => (n < 1048576 ? `${Math.max(1, Math.round(n / 1024))} KB` : `${mb(n)} MB`);
449	  let trail = [];
450	  const take = async (id, name) => {
451	    if (busy) return;
452	    msg('Downloading ' + (name || 'the stack') + '…');
453	    let what;
454	    try {
455	      const f = await drive.file(id, name, (n) => {
456	        what = n; busy = true; $('drive-dlg').close(); msg(''); progress(`Downloading ${n}…`, null);
457	      }, (got, total) => progress(`Downloading ${what} · ${mb(got)}${total ? ' of ' + mb(total) : ''} MB`, total ? got / total : null));
458	      if (f.folder) { trail = [f]; return show_(); }
459	      busy = false;
460	      openBytes(f.name, f.bytes);
461	    } catch (err) {
462	      busy = false; $('progress').hidden = true;
463	      if (!$('drive-dlg').open) $('drive-dlg').showModal();
464	      msg(err.message || String(err), true);
465	    }
466	  };
467	  const show_ = async () => {
468	    const at = trail[trail.length - 1];
469	    $('drive-path').innerHTML = trail.map((t, k) => `<button type="button" data-k="${k}">${esc(t.name)}</button>`).join(' / ');
470	    $('drive-path').querySelectorAll('button').forEach((b) => (b.onclick = () => { trail = trail.slice(0, +b.dataset.k + 1); show_(); }));
471	    $('drive-list').replaceChildren(); msg('Reading the folder…');
472	    try {
473	      const items = await drive.list(at.id);
474	      msg(items.length ? '' : 'No TIFF stacks here.');
475	      for (const f of items) {
476	        const b = document.createElement('button'); b.type = 'button'; b.className = 'item' + (f.folder ? ' folder' : '');
477	        const meta = [f.size == null ? '' : sizeText(f.size),
478	          f.created ? f.created.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : ''].filter(Boolean).join(' · ');
479	        b.innerHTML = `<span class="name">${esc(f.name)}</span><span class="meta">${esc(meta)}</span>`;
480	        b.onclick = () => (f.folder ? (trail.push(f), show_()) : take(f.id, f.name));
481	        $('drive-list').append(b);
482	      }
483	    } catch (err) { msg(err.message || String(err), true); }
484	  };
485	  if (!drive.ready) {
486	    const d = document.querySelector('#load-menu .item[data-src="drive"]');
487	    d.disabled = true; d.title = 'Needs this site’s Google API key, which has not been set up yet';
488	    d.textContent = 'From Google Drive (not set up yet)';
489	  }
490	  const open = () => {
491	    const link = $('drive-link').value, ref = drive.parse(link);
492	    $('drive-list').replaceChildren(); $('drive-path').replaceChildren();
493	    if (!ref) return msg('That does not look like a Google Drive link.', true);
494	    store.set(DRIVE_LINK, link);
495	    if (ref.kind === 'file') return take(ref.id);
496	    trail = [{ id: ref.id, name: 'Folder' }]; show_();
497	  };
498	  $('drive-go').onclick = open;
499	  $('drive-link').addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); open(); } });
500	}
501	
502	try { maxTextureSide(); } catch (err) {
503	  $('load-main').disabled = true; $('empty-msg').textContent = err.message;
504	}
505	// Turns an opened TIFF stack into what the viewer draws: one 8-bit volume per channel, binned in x-y
506	// to fit the GPU, each scaled by one brightness window over the whole stack, never per slice, so
507	// signal that fades with depth still looks faded. The same scaling as analysis/export_stack_view.py.
508	
509	const WINDOW_PCT = [0.5, 99.9];
510	// GPU budget, not a property of the data: the ray-caster samples every voxel a ray crosses, so a
511	// side much past this turns rotation into a slideshow on a laptop.
512	const MAX_SIDE = 640;
513	
514	export const binFor = (width, height, maxSide = MAX_SIDE) => Math.max(1, Math.ceil(Math.max(width, height) / maxSide));
515	
516	// onProgress(done, total) after each plane read; resolves to {meta, vols} where vols[c] is a
517	// Uint8Array of Z*Y*X voxels, slice by slice
518	export async function buildVolumes(stack, { bin = binFor(stack.width, stack.height), onProgress } = {}) {
519	  const { width: W, height: H, channels: C, slices: Z } = stack;
520	  const X = Math.floor(W / bin), Y = Math.floor(H / bin), n = X * Y, k = 1 / (bin * bin);
521	  const meta = {
522	    shape: [Z, Y, X], bin, channels: [],
523	    um_per_px: stack.umPerPx ? stack.umPerPx * bin : null,
524	    z_step_um: stack.zStep, frames: stack.frames, layout: stack.layout, bits: stack.bits,
525	  };
526	  const vols = [];
527	  for (let c = 0; c < C; c++) {
528	    const f = new Float32Array(Z * n);
529	    for (let z = 0; z < Z; z++) {
530	      const src = await stack.page(c, z), dst = z * n;
531	      for (let y = 0; y < Y * bin; y++) {
532	        const row = y * W, out = dst + Math.floor(y / bin) * X;
533	        for (let x = 0; x < X * bin; x++) f[out + Math.floor(x / bin)] += src[row + x];
534	      }
535	      if (bin > 1) for (let i = dst; i < dst + n; i++) f[i] *= k;
536	      if (onProgress) onProgress(c * Z + z + 1, C * Z);
537	      await new Promise((r) => setTimeout(r, 0));
538	    }
539	    const [lo, hi] = percentiles(f, WINDOW_PCT);
540	    const u8 = new Uint8Array(f.length), s = 255 / Math.max(hi - lo, 1e-9);
541	    for (let i = 0; i < f.length; i++) u8[i] = Math.min(Math.max((f[i] - lo) * s, 0), 255);
542	    vols.push(u8);
543	    const p50 = [], p99 = [];
544	    for (let z = 0; z < Z; z++) {
545	      const [a, b] = percentiles(u8.subarray(z * n, (z + 1) * n), [50, 99]);
546	      p50.push(Math.round(a * 10) / 10); p99.push(Math.round(b * 10) / 10);
547	    }
548	    meta.channels.push({ name: stack.names ? stack.names[c] : `Channel ${c + 1}`, window_raw: [lo, hi], slice_p50: p50, slice_p99: p99 });
549	  }
550	  return { meta, vols };
551	}
552	
553	// linear-interpolated percentiles, as numpy's default, from a fine histogram rather than a sort
554	export function percentiles(a, pcts) {
555	  let mn = Infinity, mx = -Infinity;
556	  for (let i = 0; i < a.length; i++) { const v = a[i]; if (v < mn) mn = v; if (v > mx) mx = v; }
557	  if (!(mx > mn)) return pcts.map(() => mn);
558	  const B = 1 << 16, hist = new Uint32Array(B), s = (B - 1) / (mx - mn);
559	  for (let i = 0; i < a.length; i++) hist[Math.round((a[i] - mn) * s)]++;
560	  return pcts.map((p) => {
561	    const rank = (p / 100) * (a.length - 1), lo = Math.floor(rank), frac = rank - lo;
562	    let seen = 0, b = 0;
563	    for (; b < B; b++) { seen += hist[b]; if (seen > lo) break; }
564	    let v = mn + b / s;
565	    if (frac > 0 && seen <= lo + 1) { let b2 = b + 1; while (b2 < B && !hist[b2]) b2++; if (b2 < B) v += frac * (b2 - b) / s; }
566	    return v;
567	  });
568	}
