# the root index.html forwards to it.
publish_root=.
publish_paths=index.html microviewer
# writes microviewer/config.js: the Drive folder from data/sources.json, and the Google API key
# when the repository has a GOOGLE_API_KEY variable (optional, so it is not a build_var)
build_command=node microviewer/build.mjs
<!doctype html>
<meta charset="utf-8">
<title>3D MicroViewer</title>
<meta http-equiv="refresh" content="0; url=microviewer/">
<a href="microviewer/">3D MicroViewer</a>
:root {
  color-scheme: dark;
  --ground: #0b0f12;
  --panel: #131a1f;
  --line: #25313a;
  --text: #d8e1e7;
  --muted: #82929d;
  --accent: #4fd1d9;
  --warn: #e8b04a;
  --mark: #ff4fd8;
  --sans: "IBM Plex Sans", system-ui, sans-serif;
  --cond: "IBM Plex Sans Condensed", "Arial Narrow", system-ui, sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, monospace;
}
html, body { height: 100%; }
body { background: var(--ground); color: var(--text); font: 14px/1.5 var(--sans); padding-inline: 16px; padding-block: 12px 24px; }
header { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 16px; margin-bottom: 10px; }
h1 { font: 600 22px/1.2 var(--cond); margin: 0; letter-spacing: .01em; text-wrap: balance; }
.facts { display: flex; flex-wrap: wrap; gap: 4px 14px; font: 12px var(--mono); color: var(--muted); font-variant-numeric: tabular-nums; }
.facts b { color: var(--text); font-weight: 500; }
.guess { color: var(--warn); }
.layout { display: grid; grid-template-columns: minmax(0, 1fr) 280px; gap: 14px; align-items: start; }
@media (max-width: 820px) { .layout { grid-template-columns: minmax(0, 1fr); } }
.stage { position: relative; background: #000; border: 1px solid var(--line); border-radius: 4px; aspect-ratio: 4 / 3; max-width: 100%; overflow: hidden; touch-action: none; }
.stage canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
#gl { cursor: grab; }
#gl:active { cursor: grabbing; }
#hud { pointer-events: none; }
.hint { position: absolute; left: 10px; bottom: 8px; font: 11px var(--mono); color: var(--muted); pointer-events: none; }
#status { position: absolute; inset: 0; display: grid; place-items: center; font: 13px var(--mono); color: var(--muted); padding: 16px; text-align: center; }
aside { display: flex; flex-direction: column; gap: 14px; background: var(--panel); border: 1px solid var(--line); border-radius: 4px; padding: 14px; }
fieldset { border: 0; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 6px; }
legend { font: 600 11px var(--cond); text-transform: uppercase; letter-spacing: .08em; color: var(--muted); margin-bottom: 4px; padding: 0; }
.seg { display: flex; border: 1px solid var(--line); border-radius: 3px; overflow: hidden; }
.seg button { flex: 1; background: transparent; color: var(--text); border: 0; border-right: 1px solid var(--line); padding: 6px 4px; font: 12px var(--sans); cursor: pointer; }
.seg button:last-child { border-right: 0; }
.seg button[aria-pressed="true"] { background: var(--accent); color: #062326; font-weight: 500; }
button:focus-visible, input:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
label.row { display: grid; grid-template-columns: 1fr auto; gap: 2px 8px; font-size: 12px; color: var(--muted); }
label.row output { font: 12px var(--mono); color: var(--text); font-variant-numeric: tabular-nums; }
label.row input[type=range] { grid-column: 1 / -1; width: 100%; accent-color: var(--accent); margin: 0; }
label.check { display: flex; gap: 8px; align-items: center; font-size: 13px; }
label.check input { accent-color: var(--accent); }
.views { display: flex; gap: 6px; flex-wrap: wrap; }
.views button { background: transparent; color: var(--text); border: 1px solid var(--line); border-radius: 3px; padding: 4px 9px; font: 12px var(--sans); cursor: pointer; }
.views button:hover { border-color: var(--accent); }
.note { font-size: 12px; color: var(--muted); margin: 0; }
.note.warn { color: var(--warn); }
h2 { font: 600 16px/1.3 var(--cond); margin: 22px 0 8px; letter-spacing: .01em; }
.flat { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 14px; align-items: start; }
@media (max-width: 820px) { .flat { grid-template-columns: minmax(0, 1fr); } }
.flat canvas { width: 100%; max-width: 100%; aspect-ratio: 1; image-rendering: pixelated; background: #000; border: 1px solid var(--line); border-radius: 4px; display: block; }
.cap { font: 12px var(--mono); color: var(--muted); margin-top: 4px; }
.depth svg { width: 100%; height: auto; display: block; }
.depth { background: var(--panel); border: 1px solid var(--line); border-radius: 4px; padding: 12px; display: flex; flex-direction: column; gap: 8px; }
.legend-bar { height: 8px; border-radius: 2px; background: linear-gradient(90deg, #3e4fb8, #29a8e6, #2fe0a0, #b7f23a, #f7b92a, #e8551a); }
p.lede { max-width: 72ch; color: var(--muted); margin: 0 0 12px; }
@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
body { margin: 0; }
[hidden] { display: none !important; }
header .grow { flex: 1; }
button.primary { background: var(--accent); color: #062326; border: 0; border-radius: 3px; padding: 7px 14px; font: 500 13px var(--sans); cursor: pointer; }
button.primary:disabled { opacity: .4; cursor: default; }
.split { display: inline-flex; position: relative; }
.split > button.primary { border-radius: 3px 0 0 3px; }
.split summary { list-style: none; background: var(--accent); color: #062326; border-left: 1px solid #0a4a4f; border-radius: 0 3px 3px 0; padding: 7px 9px; cursor: pointer; font: 13px var(--sans); }
.split summary::-webkit-details-marker { display: none; }
.split summary::after { content: "▾"; }
.pop { position: absolute; right: 0; top: calc(100% + 4px); z-index: 5; background: var(--panel); border: 1px solid var(--line); border-radius: 4px; padding: 4px; display: flex; flex-direction: column; min-width: 190px; box-shadow: 0 6px 18px rgba(0,0,0,.5); }
.pop .item, #drive-list .item { background: transparent; color: var(--text); border: 0; border-radius: 3px; padding: 7px 10px; text-align: left; font: 13px var(--sans); cursor: pointer; }
.pop .item:hover, #drive-list .item:hover { background: #1d2a31; }
.pop .item:disabled { opacity: .45; cursor: default; background: transparent; }
#empty { border: 1px dashed var(--line); border-radius: 6px; padding: 48px 20px; text-align: center; color: var(--muted); max-width: 720px; margin: 40px auto; }
#empty h2 { margin-top: 0; color: var(--text); }
#empty.over, body.over #empty { border-color: var(--accent); color: var(--text); }
#empty p { margin: 8px auto; max-width: 60ch; }
.err { color: #ff8a7a; }
#progress-bar { width: min(320px, 70%); height: 4px; background: var(--line); border-radius: 2px; overflow: hidden; margin: 10px auto 0; }
#progress-bar i { display: block; height: 100%; width: 0; background: var(--accent); }
dialog { background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 6px; width: min(560px, calc(100vw - 32px)); padding: 16px; }
dialog::backdrop { background: rgba(0,0,0,.6); }
dialog h2 { margin: 0 0 6px; }
.drive-row { display: flex; gap: 8px; align-items: center; margin-top: 10px; }
.drive-row.end { justify-content: space-between; }
.drive-row input { flex: 1; min-width: 0; background: var(--ground); color: var(--text); border: 1px solid var(--line); border-radius: 3px; padding: 7px 8px; font: 13px var(--sans); }
.drive-row button:not(.primary) { background: transparent; color: var(--text); border: 1px solid var(--line); border-radius: 3px; padding: 6px 12px; cursor: pointer; font: 13px var(--sans); }
#drive-path { margin-top: 10px; font: 12px var(--mono); color: var(--muted); white-space: nowrap; overflow-x: auto; }
#drive-path button { background: none; border: 0; color: var(--accent); cursor: pointer; font: inherit; padding: 0; }
#drive-list { display: flex; flex-direction: column; max-height: 320px; overflow: auto; margin-top: 6px; }
#drive-list .item { display: flex; justify-content: space-between; gap: 12px; }
#drive-list .item.folder .name::before { content: "▸ "; color: var(--muted); }
#drive-list .meta { font: 12px var(--mono); color: var(--muted); white-space: nowrap; }
.hint-text { font-size: 12px; color: var(--muted); }
.legend-ends { display: flex; justify-content: space-between; font: 11px var(--mono); color: var(--muted); }
footer#version { margin-top: 24px; text-align: right; }
