          const to = pick(ev);
          if (to && !(to.segment != null && to.segment === h.segment)) apply(Mo.connect(model, h, to));
          V.redraw();
        } else if (h) openMenu(h, ev.clientX, ev.clientY);
      },
      cancel() { rubber = null; cv.classList.remove('connecting'); V.redraw(); },
    };
  }
  return null;
