function openMenu(h, x, y) {
  const items = [];
  const zScale = V.S.zs / model.um_per_px * model.um_per_px;   // µm per slice, as the view draws it
  if (h.segment != null) {
    items.push(['Delete this segment', () => Mo.deleteSegment(model, h.segment)]);
