import { chromium } from '/opt/node-tools/node_modules/playwright/index.mjs';
const [stack, out] = process.argv.slice(2);
const b = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
const p = await b.newPage({ viewport: { width: 1500, height: 1000 }, acceptDownloads: true });
p.on('pageerror', (e) => console.log('pageerror:', e.message));
await p.goto('http://localhost:8765/microviewer/');
await p.setInputFiles('#file', stack);
await p.waitForSelector('#viewer:not([hidden])', { timeout: 120000 });
await p.waitForSelector('#model-draft:not([hidden])'); await p.click('#model-draft');
await p.waitForSelector('#model-on:not([hidden])'); await p.waitForTimeout(800);
const st = () => p.evaluate(async () => { const m = await import('./modelview.js'); return m.inspect(); });
const box = await p.locator('#mcv').boundingBox();
const at = (pt) => [box.x + pt[0], box.y + pt[1]];
let s = await st();
const deg = {}; for (const g of s.model.segments) for (const k of [g.a, g.b]) deg[k] = (deg[k] || 0) + 1;
const center = [box.width / 2, box.height / 2];
const near = (pred) => Object.entries(s.points).filter(([id]) => pred(+id)).sort((a, b) => Math.hypot(a[1][0]-center[0], a[1][1]-center[1]) - Math.hypot(b[1][0]-center[0], b[1][1]-center[1]))[0];
const log = async (what) => { s = await st(); const d = {}; for (const g of s.model.segments) for (const k of [g.a, g.b]) d[k] = (d[k] || 0) + 1;
  console.log(what, '→ segments', s.model.segments.length, 'junctions', Object.values(d).filter((v) => v >= 3).length, 'edits', s.edits); };
await log('start');
// 1. right-click a junction → split
const [jid, jp] = near((id) => deg[id] >= 3);
await p.mouse.click(...at(jp), { button: 'right' });
await p.waitForSelector('#ctx:not([hidden])');
console.log('menu:', await p.locator('#ctx .item').allTextContents());
await p.screenshot({ path: `${out}/menu.png`, clip: { x: box.x + jp[0] - 150, y: box.y + jp[1] - 120, width: 420, height: 260 } });
await p.locator('#ctx .item', { hasText: 'Wrong junction' }).click();
await log(`split junction ${jid}`);
// 2. drag a bend point 40px right
const [bid, bp] = near((id) => deg[id] === 2);
await p.mouse.move(...at(bp)); await p.mouse.down(); await p.mouse.move(at(bp)[0] + 40, at(bp)[1], { steps: 5 }); await p.mouse.up();
await log(`dragged point ${bid}`);
console.log('moved from', bp.slice(0,2).map(Math.round), 'to', s.points[bid].slice(0,2).map(Math.round));
// 3. right-click a segment → delete
const g = s.model.segments[10], a = s.points[g.a], c = s.points[g.b];
await p.mouse.click(...at([(a[0]+c[0])/2, (a[1]+c[1])/2]), { button: 'right' });
console.log('segment menu:', await p.locator('#ctx .item').allTextContents());
await p.locator('#ctx .item', { hasText: 'Delete this segment' }).click();
await log('deleted segment');
// 4. right-drag between two tips → connect
const tips = Object.entries(s.points).filter(([id]) => { const d = {}; for (const q of s.model.segments) for (const k of [q.a, q.b]) d[k] = (d[k] || 0) + 1; return d[id] === 1; });
const [t1, t2] = [tips[0], tips.find(([id, q]) => id !== tips[0][0] && Math.hypot(q[0]-tips[0][1][0], q[1]-tips[0][1][1]) < 120)];
await p.mouse.move(...at(t1[1])); await p.mouse.down({ button: 'right' }); await p.mouse.move(...at(t2[1]), { steps: 8 });
await p.screenshot({ path: `${out}/rubber.png`, clip: { x: box.x + Math.min(t1[1][0], t2[1][0]) - 80, y: box.y + Math.min(t1[1][1], t2[1][1]) - 80, width: 300, height: 300 } });
await p.mouse.up({ button: 'right' });
await log(`connected ${t1[0]}–${t2[0]}`);
// 5. undo, redo
await p.keyboard.press('Control+z'); await log('undo'); await p.keyboard.press('Control+Shift+z'); await log('redo');
// 6. reload: edits kept
await p.reload(); await p.setInputFiles('#file', stack); await p.waitForSelector('#viewer:not([hidden])', { timeout: 120000 });
await p.waitForSelector('#model-draft:not([hidden])'); await p.click('#model-draft'); await p.waitForTimeout(500);
await log('after reload'); console.log('msg:', await p.textContent('#model-msg'));
// 7. download
const [dl] = await Promise.all([p.waitForEvent('download'), p.click('#m-save')]);
await dl.saveAs(`${out}/corrected.json`); console.log('downloaded', dl.suggestedFilename());
await b.close();
EOF
